// Parse format: NODE_1,SOIL:65,HALL:1,MAG:0,TIP:12,TILT:26.91,RAIN:44.04,RSSI:-65,SNR:8.5
var raw = msg.payload;

try {
    var parts = raw.split(',');
    if (parts.length < 6) {
        node.warn('Format data tidak valid: ' + raw);
        return null;
    }

    var data = {
        node: parts[0].trim()
    };

    // Parse key:value pairs
    for (var i = 1; i < parts.length; i++) {
        var kv = parts[i].split(':');
        if (kv.length === 2) {
            var key = kv[0].trim().toLowerCase();
            var val = kv[1].trim();

            if (key === 'soil' || key === 'hall' || key === 'mag' || key === 'tip' || key === 'rssi') {
                data[key] = parseInt(val) || 0;
            } else if (key === 'tilt' || key === 'rain' || key === 'snr') {
                data[key] = parseFloat(val) || 0;
            }
        }
    }

    // Tambahkan timestamp
    data.timestamp = new Date().toISOString();

    // Pastikan semua field ada
    data.soil = data.soil || 0;
    data.hall = data.hall || 0;
    data.mag = data.mag || 0;
    data.tip = data.tip || 0;
    data.tilt = data.tilt || 0;
    data.rain = data.rain || 0;
    data.rssi = data.rssi || 0;
    data.snr = data.snr || 0;

    msg.payload = data;
    return msg;

} catch (e) {
    node.error('Error parsing: ' + e.message);
    return null;
}

var data = msg.payload;
var nodeId = data.node;
var tilt = data.tilt;
var THRESHOLD = 45;  // Derajat
var COOLDOWN_MS = 5 * 60 * 1000;  // 5 menit

// Cek apakah melebihi threshold
if (tilt >= THRESHOLD) {
    // Cek cooldown per node
    var lastAlert = flow.get('lastAlert_' + nodeId) || 0;
    var now = Date.now();

    if (now - lastAlert > COOLDOWN_MS) {
        // Update waktu terakhir alert
        flow.set('lastAlert_' + nodeId, now);

        // Buat pesan Telegram
        var waktu = new Date().toLocaleString('id-ID', {
            timeZone: 'Asia/Jakarta',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        });

        var pesan = '🚨 *EWS ALERT - BAHAYA LONGSOR* 🚨\n\n'
            + '⚠️ Kemiringan tanah mencapai *' + tilt.toFixed(2) + '°*!\n\n'
            + '📍 *Lokasi:* ' + nodeId.replace('_', ' ') + ' — Sampok, Sriharjo, Imogiri\n'
            + '🔺 *Kemiringan:* ' + tilt.toFixed(2) + '°\n'
            + '💧 *Kelembapan:* ' + data.soil + '%\n'
            + '🌧️ *Curah Hujan:* ' + data.tip + ' tip (' + (data.tip * 3.67).toFixed(1) + ' ml)\n'
            + '📶 *RSSI:* ' + data.rssi + ' dBm\n'
            + '⏰ *Waktu:* ' + waktu + '\n\n'
            + '⚠️ Segera lakukan evakuasi jika diperlukan!';

        msg.payload = {
            chatId: '',  // ⚠️ ISI DENGAN CHAT ID TELEGRAM ANDA
            type: 'message',
            content: pesan,
            options: {
                parse_mode: 'Markdown'
            }
        };

        node.status({fill: 'red', shape: 'dot', text: 'Alert ' + nodeId + ' @ ' + tilt.toFixed(1) + '°'});
        return msg;
    } else {
        // Cooldown aktif
        var sisaCooldown = Math.ceil((COOLDOWN_MS - (now - lastAlert)) / 1000);
        node.status({fill: 'yellow', shape: 'ring', text: 'Cooldown ' + nodeId + ': ' + sisaCooldown + 's'});
        return null;
    }
}

// Normal - tidak kirim
node.status({fill: 'green', shape: 'dot', text: nodeId + ': ' + tilt.toFixed(1) + '° (Normal)'});
return null;

var hours = msg.req.query.hours || 24;
var nodeFilter = msg.req.query.node || '';

var sql = 'SELECT * FROM sensor_data WHERE timestamp >= datetime("now", "-' + hours + ' hours")';

if (nodeFilter) {
    sql += " AND node = '" + nodeFilter + "'";
}

sql += ' ORDER BY timestamp ASC LIMIT 2000';
msg.topic = sql;
return msg;

